function workingPairs(power: number[], boost: number[], need: number): number[] {
  const b = [...boost].sort((x, y) => x - y);
  const m = b.length;
  return power.map(p => {
    let lo = 0, hi = m; // first index where p * b[i] >= need
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (p * b[mid] >= need) hi = mid;
      else lo = mid + 1;
    }
    return m - lo;
  });
}

